(79,'H5P.Summary','Summary',1,10,32,1,0,'iframe','js/stop-watch.js, js/xapi-event-builder.js, js/summary.js','css/summary.css','','[\n  {\n    \"name\": \"intro\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introduction text\",\n    \"importance\": \"high\",\n    \"default\": \"Choose the correct statement.\",\n    \"description\": \"Will be displayed above the summary task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"common\": false\n  },\n  {\n    \"name\": \"summaries\",\n    \"importance\": \"high\",\n    \"type\": \"list\",\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SummaryTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"label\": \"Summary\",\n    \"entity\": \"statements\",\n    \"max\": 100,\n    \"min\": 1,\n    \"field\": {\n      \"name\": \"statements\",\n      \"type\": \"group\",\n      \"label\": \"Set of statements\",\n      \"importance\": \"high\",\n      \"isSubContent\": true,\n      \"fields\": [\n        {\n          \"name\": \"summary\",\n          \"type\": \"list\",\n          \"label\": \"List of statements for the summary - the first statement is correct.\",\n          \"entity\": \"statement\",\n          \"importance\": \"medium\",\n          \"min\": 2,\n          \"field\": {\n            \"name\": \"text\",\n            \"type\": \"text\",\n            \"label\": \"Statement\",\n            \"importance\": \"medium\",\n            \"widget\": \"html\",\n            \"enterMode\": \"p\",\n            \"tags\": []\n          }\n        },\n        {\n          \"name\": \"tip\",\n          \"type\": \"group\",\n          \"label\": \"Tip\",\n          \"importance\": \"low\",\n          \"optional\": true,\n    