(119,'H5P.ThreeImage','Virtual Tour (360)',0,5,8,1,1,'iframe','dist/h5p-three-image.js','dist/h5p-three-image.css','','[\n  {\n    \"name\": \"threeImage\",\n    \"type\": \"group\",\n    \"widget\": \"threeImage\",\n    \"label\": \"Three Image Editor\",\n    \"importance\": \"high\",\n    \"fields\": [\n      {\n        \"name\": \"scenes\",\n        \"type\": \"list\",\n        \"label\": \"Scenes\",\n        \"entity\": \"Scene\",\n        \"min\": 0,\n        \"field\": {\n          \"name\": \"scene\",\n          \"type\": \"group\",\n          \"fields\": [\n            {\n              \"name\": \"sceneType\",\n              \"type\": \"select\",\n              \"label\": \"Scene type\",\n              \"widget\": \"radioGroup\",\n              \"alignment\": \"horizontal\",\n              \"options\": [\n                {\n                  \"value\": \"360\",\n                  \"label\": \"360 image\"\n                },\n                {\n                  \"value\": \"static\",\n                  \"label\": \"Static image\"\n                }\n              ],\n              \"default\": \"360\"\n            },\n            {\n              \"name\": \"showBackButton\",\n              \"type\": \"boolean\",\n              \"label\": \"Display \\\"Back\\\" button\",\n              \"description\": \"Display button for navigating back to your previous scene\",\n              \"default\": true,\n              \"widget\": \"showWhen\",\n              \"showWhen\": {\n                \"rules\": [\n                  {\n                    \"field\": \"sceneType\",\n                    \"equals\": \"static\"\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"sceneId\",\n              \"type\": \"number\"\n            },\n            {\n              \"name\": \"scenename\",\n              \"type\": \"text\",\n              \"label\": \"Scene Title\",\n              \"description\": \"Used to identify the scene\"\n            },\n            {\n              \"name\": \"scenesrc\",\n              \"type\": \"image\",\n              \"label\": \"Scene Background\"\n            },\n            {\n              \"name\": \"scenedescription\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Scene Description\",\n              \"description\": \"A text that can describe the scene for the end-user\",\n              \"optional\": true,\n              \"tags\": [\n                \"p\",\n                \"br\",\n                \"strong\",\n                \"em\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"cameraStartPosition\",\n              \"type\": \"text\"\n            },\n            {\n              \"name\": \"interactions\",\n              \"type\": \"list\",\n              \"min\": 0,\n              \"field\": {\n                \"name\": \"interaction\",\n                \"type\": \"group\",\n                \"fields\": [\n                  {\n                    \"name\": \"labelText\",\n                    \"type\": \"text\",\n                    \"label\": \"Label\",\n                    \"optional\": true,\n                    \"description\": \"If left blank no label will be displayed and we\'ll try to use the title field for screen readers\"\n                  },\n                  {\n                    \"name\": \"label\",\n                    \"type\": \"group\",\n                    \"label\": \"Label Settings\",\n                    \"importance\": \"low\",\n                    \"fields\": [\n                      {\n                        \"name\": \"labelPosition\",\n                        \"type\": \"select\",\n                        \"label\": \"Label position\",\n                        \"description\": \"Choose where the label should appear\",\n                        \"options\": [\n                          {\n                            \"value\": \"inherit\",\n                            \"label\": \"Use behavioral setting\"\n                          },\n                          {\n                            \"value\": \"right\",\n                            \"label\": \"Right aligned\"\n                          },\n                          {\n                            \"value\": \"left\",\n                            \"label\": \"Left aligned\"\n                          },\n                          {\n                            \"value\": \"top\",\n                            \"label\": \"Top aligned\"\n                          },\n                          {\n                            \"value\": \"bottom\",\n                            \"label\": \"Bottom aligned\"\n                          }\n                        ],\n                        \"default\": \"inherit\"\n                      },\n                      {\n                        \"name\": \"showLabel\",\n                        \"type\": \"select\",\n                        \"label\": \"Display Label\",\n                        \"description\": \"If hidden - labels will show only on mouse over\",\n                        \"options\": [\n                          {\n                            \"value\": \"inherit\",\n                            \"label\": \"Use behavioral setting\"\n                          },\n                          {\n                            \"value\": \"show\",\n                            \"label\": \"Show\"\n                          },\n                          {\n                            \"value\": \"hide\",\n                            \"label\": \"Hide\"\n                          }\n                        ],\n                        \"default\": \"inherit\"\n                      }\n                    ]\n                  },\n                  {\n                    \"name\": \"action\",\n                    \"type\": \"library\",\n                    \"options\": [\n                      \"H5P.GoToScene 0.1\",\n                      \"H5P.AdvancedText 1.1\",\n                      \"H5P.Image 1.1\",\n                      \"H5P.Audio 1.5\",\n                      \"H5P.Video 1.6\",\n                      \"H5P.Summary 1.10\",\n                      \"H5P.SingleChoiceSet 1.11\"\n                    ]\n                  },\n                  {\n                    \"name\": \"interactionpos\",\n                    \"type\": \"text\"\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"iconType\",\n              \"type\": \"select\",\n              \"label\": \"Button style\",\n              \"description\": \"Decide how buttons pointing to this scene should look. For scenes that are static and does not lead to new scenes, we recommend the \\\"More information\\\" button.\",\n              \"widget\": \"radioGroup\",\n              \"alignment\": \"horizontal\",\n              \"options\": [\n                {\n                  \"value\": \"arrow\",\n                  \"label\": \"New scene (arrow)\"\n                },\n                {\n                  \"value\": \"plus\",\n                  \"label\": \"More information (plus)\"\n                }\n              ],\n              \"default\": \"arrow\"\n            },\n            {\n              \"name\": \"audio\",\n              \"type\": \"audio\",\n              \"label\": \"Audio Track\",\n              \"description\": \"Add an audio track that\'s specific for this scene.\",\n              \"optional\": true,\n              \"widgetExtensions\": [\n                \"AudioRecorder\"\n              ]\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"startSceneId\",\n        \"type\": \"number\",\n        \"default\": 0\n      },\n      {\n        \"name\": \"audio\",\n        \"type\": \"audio\",\n        \"label\": \"Audio track\",\n        \"optional\": true\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioral settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the world behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"audio\",\n        \"type\": \"audio\",\n        \"label\": \"Global Audio\",\n        \"description\": \"Add an audio track that\'s available for all of the scenes by default.\",\n        \"optional\": true,\n        \"widgetExtensions\": [\n          \"AudioRecorder\"\n        ]\n      },\n      {\n        \"name\": \"sceneRenderingQuality\",\n        \"type\": \"select\",\n        \"label\": \"Scene rendering quality\",\n        \"description\": \"Choose the amount of width and height segments used to render a scene. This directly affects the quality level of the scene, try increasing the quality if a scene looks \\\"blocky\\\" or \\\"waves\\\" are seen within the scenes. Note that higher quality rendering takes more time to load.\",\n        \"options\": [\n          {\n            \"value\": \"high\",\n            \"label\": \"High Quality (128x128)\"\n          },\n          {\n            \"value\": \"medium\",\n            \"label\": \"Medium Quality (64x64)\"\n          },\n          {\n            \"value\": \"low\",\n            \"label\": \"Low Quality (16x16)\"\n          }\n        ],\n        \"default\": \"high\"\n      },\n      {\n        \"name\": \"label\",\n        \"type\": \"group\",\n        \"label\": \"Label settings\",\n        \"importance\": \"low\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"labelPosition\",\n            \"type\": \"select\",\n            \"label\": \"Label position\",\n            \"description\": \"The default label position. The position may be overriden per interaction\",\n            \"options\": [\n              {\n                \"value\": \"right\",\n                \"label\": \"Right aligned\"\n              },\n              {\n                \"value\": \"left\",\n                \"label\": \"Left aligned\"\n              },\n              {\n                \"value\": \"top\",\n                \"label\": \"Top aligned\"\n              },\n              {\n                \"value\": \"bottom\",\n                \"label\": \"Bottom aligned\"\n              }\n            ],\n            \"default\": \"right\"\n          },\n          {\n            \"name\": \"showLabel\",\n            \"type\": \"boolean\",\n            \"label\": \"Display Labels\",\n            \"description\": \"If unchecked - labels will show only on mouse over\",\n            \"default\": true\n          }\n        ]\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"Localize\",\n    \"fields\": [\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Aria label for content type\",\n        \"default\": \"Virtual Tour\"\n      },\n      {\n        \"name\": \"playAudioTrack\",\n        \"type\": \"text\",\n        \"label\": \"Label for to play audio\",\n        \"default\": \"Play Audio Track\"\n      },\n      {\n        \"name\": \"pauseAudioTrack\",\n        \"type\": \"text\",\n        \"label\": \"Label to pause audio\",\n        \"default\": \"Pause Audio Track\"\n      },\n      {\n        \"name\": \"sceneDescription\",\n        \"type\": \"text\",\n        \"label\": \"Title to scene dialog\",\n        \"default\": \"Scene Description\"\n      },\n      {\n        \"name\": \"resetCamera\",\n        \"type\": \"text\",\n        \"label\": \"Label for button to reset camera\",\n        \"default\": \"Reset Camera\"\n      },\n      {\n        \"name\": \"submitDialog\",\n        \"type\": \"text\",\n        \"label\": \"Label for the submit dialog button\",\n        \"default\": \"Submit Dialog\"\n      },\n      {\n        \"name\": \"closeDialog\",\n        \"type\": \"text\",\n        \"label\": \"Label for the close dialog button\",\n        \"default\": \"Close Dialog\"\n      },\n      {\n        \"name\": \"expandButtonAriaLabel\",\n        \"type\": \"text\",\n        \"label\": \"Aria label for the expand label button\",\n        \"default\": \"Expand the visual label\"\n      },\n      {\n        \"name\": \"backgroundLoading\",\n        \"type\": \"text\",\n        \"label\": \"Label for when background image is loading in 360 scene\",\n        \"default\": \"Loading background image...\"\n      },\n      {\n        \"name\": \"noContent\",\n        \"type\": \"text\",\n        \"label\": \"Label for when there is no content\",\n        \"default\": \"No content\"\n      }\n    ]\n  }\n]',NULL,1,20,NULL,'https://h5p.org/tutorial-virtual-tour','https://h5p.org/virtual-tour-360',1),
