(124,'H5P.KewArCode','KewAr Code',1,2,2,1,0,'iframe','dist/h5p-kewar-code.js','dist/h5p-kewar-code.css','','[\n  {\n    \"name\": \"introduction\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introductory text\",\n    \"importance\": \"medium\",\n    \"optional\": true,\n    \"description\": \"This text can optionally be presented along with your code.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"sub\",\n      \"sup\",\n      \"strong\",\n      \"em\",\n      \"p\",\n      \"code\",\n      \"u\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h1\",\n      \"h2\",\n      \"h3\",\n      \"h4\",\n      \"h5\",\n      \"h6\",\n      \"pre\",\n      \"hr\",\n      \"table\"\n    ],\n    \"font\": {\n      \"size\": true,\n      \"color\": true,\n      \"background\": true\n    }\n  },\n  {\n    \"name\": \"codeType\",\n    \"type\": \"select\",\n    \"label\": \"Code type\",\n    \"description\": \"Select what kind of code you want to generate\",\n    \"options\": [\n      {\n        \"value\": \"contact\",\n        \"label\": \"Contact\"\n      },\n      {\n        \"value\": \"event\",\n        \"label\": \"Event\"\n      },\n      {\n        \"value\": \"email\",\n        \"label\": \"Email address\"\n      },\n      {\n        \"value\": \"h5p\",\n        \"label\": \"H5P\"\n      },\n      {\n        \"value\": \"location\",\n        \"label\": \"Location\"\n      },\n      {\n        \"value\": \"phone\",\n        \"label\": \"Phone number\"\n      },\n      {\n        \"value\": \"sms\",\n        \"label\": \"SMS\"\n      },\n      {\n        \"value\": \"text\",\n        \"label\": \"Text\"\n      },\n      {\n        \"value\": \"url\",\n        \"label\": \"URL\"\n      }\n    ],\n    \"default\": \"url\",\n    \"widget\": \"editorKewArCode\"\n  },\n  {\n    \"name\": \"contact\",\n    \"type\": \"group\",\n    \"label\": \"Contact\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fiel