(143,'H5P.GameMap','Game Map',1,5,4,1,0,'iframe','dist/h5p-game-map.js','dist/h5p-game-map.css','','[{\"name\":\"showTitleScreen\",\"label\":\"Show title screen\",\"description\":\"If checked, a title screen will show up when starting.\",\"type\":\"boolean\",\"default\":false,\"optional\":true},{\"name\":\"titleScreen\",\"label\":\"Title screen\",\"type\":\"group\",\"importance\":\"low\",\"fields\":[{\"name\":\"titleScreenIntroduction\",\"label\":\"Introduction\",\"type\":\"text\",\"widget\":\"html\",\"placeholder\":\"Welcome to ...\",\"optional\":true,\"enterMode\":\"div\",\"tags\":[\"sub\",\"sup\",\"strong\",\"em\",\"p\",\"code\",\"u\",\"del\",\"a\",\"ul\",\"ol\",\"hr\",\"pre\",\"code\"],\"font\":{\"size\":true,\"color\":true,\"background\":true},\"default\":\"<p style=\\\"text-align: center;\\\"></p>\"},{\"name\":\"titleScreenMedium\",\"label\":\"Title screen media\",\"type\":\"library\",\"optional\":true,\"options\":[\"H5P.Image 1.1\",\"H5P.Video 1.6\"]}],\"widget\":\"gamemapshowwhen\",\"gamemapshowwhen\":{\"rules\":[{\"field\":\"showTitleScreen\",\"equals\":true}]}},{\"name\":\"headline\",\"label\":\"Headline\",\"type\":\"text\",\"description\":\"Optional headline for the titlebar.\",\"optional\":true},{\"name\":\"gamemapSteps\",\"type\":\"group\",\"label\":\"Game map editor\",\"importance\":\"high\",\"widget\":\"wizard\",\"fields\":[{\"name\":\"backgroundImageSettings\",\"label\":\"Background\",\"type\":\"group\",\"importance\":\"high\",\"fields\":[{\"name\":\"backgroundImage\",\"type\":\"image\",\"label\":\"Background image\",\"importance\":\"high\",\"description\":\"Select an image to use as the background of the game map.\",\"optional\":true},{\"name\":\"backgroundColor\",\"type\":\"text\",\"label\":\"Background color\",\"description\":\"Choose a color to use as the background of the game map.\",\"default\":\"rgb(255, 255, 255)\",\"widget\":\"colorSelector\",\"spectrum\":{\"showInput\":true,\"showInitial\":true,\"preferredFormat\":\"rgb\"}}]},{\"name\":\"gamemap\",\"label\":\"Game map\",\"type\":\"group\",\"importance\":\"high\",\"widget\":\"gamemap\",\"fields\":[{\"name\":\"dummy\",\"type\":\"boolean\",\"widget\":\"none\",\"optional\":true},{\"name\":\"elements\",\"type\":\"list\",\"label\":\"Elements\",\"importance\":\"high\",\"entity\":\"Element\",\"field\":{\"name\":\"elements\",\"type\":\"group\",\"label\":\"Elements\",\"importance\":\"high\",\"fields\":[{\"name\":\"id\",\"type\":\"text\",\"label\":\"Id\",\"widget\":\"none\"},{\"name\":\"type\",\"type\":\"text\",\"label\":\"Type\",\"widget\":\"none\"},{\"name\":\"label\",\"type\":\"text\",\"label\":\"Stage label\",\"description\":\"This label will be displayed on top of your exercise and will help you to connect different stages with one another.\",\"importance\":\"medium\"},{\"name\":\"canBeStartStage\",\"type\":\"boolean\",\"label\":\"User can start here\",\"description\":\"If checked, this stage will be a stage that the user start at. If no stage or more than one stage can be the start stage, the starting stage will be chosen randomly.\",\"importance\":\"medium\",\"default\":false},{\"name\":\"time\",\"type\":\"group\",\"label\":\"Time limit\",\"description\":\"Define timer related settings.\",\"fields\":[{\"name\":\"timeLimit\",\"type\":\"number\",\"label\":\"Time limit\",\"description\":\"Optional time limit in seconds. If a user exceeds this time, the exercise will close, be reset, and the user will loose a life if lives are limited.\",\"min\":1,\"optional\":true},{\"name\":\"timeoutWarning\",\"type\":\"number\",\"label\":\"Timeout warning time\",\"description\":\"Optionally set when a timeout warning audio should be played (number of remaining seconds). An audio needs to be set in the audio settings.\",\"min\":1,\"optional\":true}]},{\"name\":\"accessRestrictions\",\"type\":\"group\",\"label\":\"Access restrictions\",\"description\":\"Define restrictions for unlocking.\",\"fields\":[{\"name\":\"allOrAnyRestrictionSet\",\"type\":\"select\",\"label\":\"All or any restriction set\",\"description\":\"Choose if all or any of the following restrictions need to be met.\",\"optional\":true,\"options\":[{\"value\":\"all\",\"label\":\"All\"},{\"value\":\"any\",\"label\":\"Any\"}],\"default\":\"all\"},{\"name\":\"restrictionSetList\",\"type\":\"list\",\"optional\":true,\"label\":\"Restriction sets\",\"entity\":\"restriction set\",\"widgets\":[{\"name\":\"VerticalTabs\",\"label\":\"Default\"}],\"field\":{\"name\":\"restrictionSetGroup\",\"type\":\"group\",\"label\":\"Restriction set\",\"fields\":[{\"name\":\"allOrAnyRestriction\",\"type\":\"select\",\"label\":\"All or any restriction\",\"description\":\"Choose if all or any of the following restrictions need to be met.\",\"options\":[{\"value\":\"all\",\"label\":\"All\"},{\"value\":\"any\",\"label\":\"Any\"}],\"default\":\"any\"},{\"name\":\"restrictionList\",\"type\":\"list\",\"label\":\"Restrictions\",\"entity\":\"restriction\",\"optional\":true,\"field\":{\"name\":\"restrictionGroup\",\"type\":\"group\",\"label\":\"Restriction\",\"fields\":[{\"name\":\"restrictionType\",\"label\":\"Restriction type\",\"type\":\"select\",\"optional\":true,\"options\":[{\"value\":\"totalScore\",\"label\":\"Total score\"},{\"value\":\"stageScore\",\"label\":\"Stage score\"},{\"value\":\"stageProgress\",\"label\":\"Stage progress\"},{\"value\":\"time\",\"label\":\"Time\"}],\"default\":\"totalScore\"},{\"name\":\"totalScoreGroup\",\"type\":\"group\",\"label\":\"Total score\",\"expanded\":true,\"fields\":[{\"name\":\"totalScoreOperator\",\"label\":\"Operator for total score\",\"type\":\"select\",\"optional\":true,\"options\":[{\"value\":\"lessThan\",\"label\":\"less than\"},{\"value\":\"equalTo\",\"label\":\"equal to\"},{\"value\":\"notEqualTo\",\"label\":\"not equal to\"},{\"value\":\"greaterThan\",\"label\":\"greater than\"}],\"default\":\"greaterThan\"},{\"name\":\"totalScoreValue\",\"label\":\"Value of total score to compare to\",\"type\":\"number\",\"optional\":true}],\"widget\":\"gamemapshowwhen\",\"gamemapshowwhen\":{\"rules\":[{\"field\":\"restrictionType\",\"equals\":\"totalScore\"}]}},{\"name\":\"stageScoreGroup\",\"type\":\"group\",\"label\":\"Stage score\",\"expanded\":true,\"fields\":[{\"name\":\"stageScoreId\",\"type\":\"select\",\"label\":\"Stage to get score from\",\"widget\":\"gamemapstageselect\",\"optional\":true,\"options\":[]},{\"name\":\"stageScoreOperator\",\"label\":\"Operator for stage score\",\"type\":\"select\",\"optional\":true,\"options\":[{\"value\":\"lessThan\",\"label\":\"less than\"},{\"value\":\"equalTo\",\"label\":\"equal to\"},{\"value\":\"notEqualTo\",\"label\":\"not equal to\"},{\"value\":\"greaterThan\",\"label\":\"greater than\"}],\"default\":\"before\"},{\"name\":\"stageScoreValue\",\"label\":\"Score score to compare to\",\"type\":\"number\",\"optional\":true}],\"widget\":\"gamemapshowwhen\",\"gamemapshowwhen\":{\"rules\":[{\"field\":\"restrictionType\",\"equals\":\"stageScore\"}]}},{\"name\":\"stageProgressGroup\",\"type\":\"group\",\"label\":\"Stage progress\",\"expanded\":true,\"fields\":[{\"name\":\"stageProgressId\",\"type\":\"select\",\"label\":\"Stage to get progress from\",\"widget\":\"gamemapstageselect\",\"optional\":true,\"options\":[]},{\"name\":\"stageProgressOperator\",\"label\":\"Operator for stage progress\",\"type\":\"select\",\"optional\":true,\"options\":[{\"value\":\"is\",\"label\":\"is\"},{\"value\":\"isNot\",\"label\":\"is not\"}],\"default\":\"is\"},{\"name\":\"stageProgressValue\",\"label\":\"Progress to compare to\",\"type\":\"select\",\"options\":[{\"value\":\"unstarted\",\"label\":\"not started\"},{\"value\":\"opened\",\"label\":\"started\"},{\"value\":\"completed\",\"label\":\"completed\"},{\"value\":\"cleared\",\"label\":\"completed successfully\"}],\"default\":\"open\",\"optional\":true}],\"widget\":\"gamemapshowwhen\",\"gamemapshowwhen\":{\"rules\":[{\"field\":\"restrictionType\",\"equals\":\"stageProgress\"}]}},{\"name\":\"timeGroup\",\"type\":\"group\",\"label\":\"Time\",\"expanded\":tr