(1,1,'c_function',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'#include <stdio.h>\n#include <stdlib.h>\n#include <ctype.h>\n#include <string.h>\n#include <stdbool.h>\n#include <math.h>\n#define SEPARATOR \"#<ab@17943918#@>#\"\n\n{{ STUDENT_ANSWER }}\n\nint main() {\n{% for TEST in TESTCASES %}\n   {\n    {{ TEST.testcode }};\n   }\n    {% if not loop.last %}printf(\"%s\\n\", SEPARATOR);{% endif %}\n{% endfor %}\n    return 0;\n}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'','twig',0,'',0,1,0,'','C',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'monaco',0,0,0,'','',0,0,NULL),
(2,2,'cpp_function',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'#include <iostream>\n#include <fstream>\n#include <string>\n#include <cmath>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n#define SEPARATOR \"#<ab@17943918#@>#\"\n\n{{ STUDENT_ANSWER }}\n\nint main() {\n{% for TEST in TESTCASES %}\n   {\n    {{ TEST.extra }};\n    {{ TEST.testcode }};\n   }\n    {% if not loop.last %}cout << SEPARATOR << endl;{% endif %}\n{% endfor %}\n    return 0;\n}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'','twig',0,'',0,1,0,'','cpp',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'monaco',0,0,0,'','',0,0,NULL),
