(109,112,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','class Hesap:\n    def __init__(self, sahip, bakiye=0):\n        self.sahip = sahip\n        self.bakiye = bakiye\n\n    def yatir(self, miktar):\n        if miktar <= 0:\n            raise ValueError(\'Gecersiz miktar\')\n        self.bakiye += miktar\n\n    def cek(self, miktar):\n        if miktar > self.bakiye:\n            raise ValueError(\'Yetersiz bakiye\')\n        self.bakiye -= miktar\n\n    def __str__(self):\n        return f\'Sahip: {self.sahip}, Bakiye: {self.bakiye:.2f}\'\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(110,113,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','import sys\nsatir = kelime = karakter = 0\nfor s in sys.stdin:\n    s = s.rstrip(\'\\n\')\n    if s.strip() == \'\':\n        continue\n    satir += 1\n    kelime += len(s.split())\n    karakter += len(s.replace(\' \', \'\'))\nprint(f\'Satir: {satir}\')\nprint(f\'Kelime: {kelime}\')\nprint(f\'Karakter: {karakter}\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(111,114,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def ikili_ara(liste, x):\n    sol, sag = 0, len(liste) - 1\n    while sol <= sag:\n        orta = (sol + sag) // 2\n        if liste[orta] == x:\n            return orta\n        if liste[orta] < x:\n            sol = orta + 1\n        else:\n            sag = orta - 1\n    return -1\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(112,115,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def sirala(liste):\n    l = list(liste)\n    n = len(l)\n    for i in range(n):\n        for j in range(n - 1 - i):\n            if l[j] > l[j + 1]:\n                l[j], l[j + 1] = l[j + 1], l[j]\n    return l\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(113,116,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def dengeli_mi(s):\n    cift = {\')\': \'(\', \']\': \'[\', \'}\': \'{\'}\n    y = []\n    for c in s:\n        if c in \'([{\':\n            y.append(c)\n        elif c in cift:\n            if not y or y.pop() != cift[c]:\n                return False\n    return not y\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(114,117,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','a = int(input())\nb = int(input())\nc = int(input())\nprint(f\'{(a + b + c) / 3:.2f}\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(115,118,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def harf(not_):\n    if not_ < 0 or not_ > 100:\n        return \'Gecersiz\'\n    if not_ >= 90:\n        return \'AA\'\n    if not_ >= 80:\n        return \'BA\'\n    if not_ >= 70:\n        return \'BB\'\n    if not_ >= 60:\n        return \'CB\'\n    if not_ >= 50:\n        return \'CC\'\n    return \'FF\'\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(116,119,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def asal_mi(n):\n    if n < 2:\n        return False\n    i = 2\n    while i * i <= n:\n        if n % i == 0:\n            return False\n        i += 1\n    return True\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(117,120,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def palindrom_mu(s):\n    t = s.replace(\' \', \'\').lower()\n    return t == t[::-1]\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(118,121,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','s = input().lower()\nsayac = {}\nfor c in s:\n    if c.isalpha():\n        sayac[c] = sayac.get(c, 0) + 1\nfor harf, adet in sorted(sayac.items(), key=lambda x: (-x[1], x[0])):\n    print(f\'{harf}: {adet}\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(119,122,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','class Hesap:\n    def __init__(self, sahip, bakiye=0):\n        self.sahip = sahip\n        self.bakiye = bakiye\n\n    def yatir(self, miktar):\n        if miktar <= 0:\n            raise ValueError(\'Gecersiz miktar\')\n        self.bakiye += miktar\n\n    def cek(self, miktar):\n        if miktar > self.bakiye:\n            raise ValueError(\'Yetersiz bakiye\')\n        self.bakiye -= miktar\n\n    def __str__(self):\n        return f\'Sahip: {self.sahip}, Bakiye: {self.bakiye:.2f}\'\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(120,123,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','t = int(input())\nprint(f\'{t // 3600} saat {t % 3600 // 60} dakika {t % 60} saniye\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(121,124,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def ucgen_turu(a, b, c):\n    if min(a, b, c) <= 0 or max(a, b, c) >= a + b + c - max(a, b, c):\n        return \'Gecersiz\'\n    if a == b == c:\n        return \'Eskenar\'\n    if a == b or b == c or a == c:\n        return \'Ikizkenar\'\n    return \'Caliskenar\'\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(122,125,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','n = int(input())\nfor i in range(1, n + 1):\n    if i % 15 == 0:\n        print(\'FizzBuzz\')\n    elif i % 3 == 0:\n        print(\'Fizz\')\n    elif i % 5 == 0:\n        print(\'Buzz\')\n    else:\n        print(i)\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(123,126,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def sifrele(metin, kaydir):\n    sonuc = \'\'\n    for c in metin:\n        if \'a\' <= c <= \'z\':\n            sonuc += chr((ord(c) - 97 + kaydir) % 26 + 97)\n        elif \'A\' <= c <= \'Z\':\n            sonuc += chr((ord(c) - 65 + kaydir) % 26 + 65)\n        else:\n            sonuc += c\n    return sonuc\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(124,127,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def tekrarsiz(liste):\n    gorulen = set()\n    sonuc = []\n    for x in liste:\n        if x not in gorulen:\n            gorulen.add(x)\n            sonuc.append(x)\n    return sonuc\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(125,128,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def dengeli_mi(s):\n    cift = {\')\': \'(\', \']\': \'[\', \'}\': \'{\'}\n    y = []\n    for c in s:\n        if c in \'([{\':\n            y.append(c)\n        elif c in cift:\n            if not y or y.pop() != cift[c]:\n                return False\n    return not y\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(126,129,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','a = int(input())\nb = int(input())\nprint(a // b, a % b)\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(127,130,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def artik_mi(yil):\n    return (yil % 4 == 0 and yil % 100 != 0) or yil % 400 == 0\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(128,131,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def basamak_toplami(n):\n    n = abs(n)\n    t = 0\n    while n > 0:\n        t += n % 10\n        n //= 10\n    return t\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(129,132,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def anagram_mi(a, b):\n    f = lambda s: sorted(s.replace(\' \', \'\').lower())\n    return f(a) == f(b)\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(130,133,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def iki_toplam(liste, hedef):\n    for i in range(len(liste)):\n        for j in range(i + 1, len(liste)):\n            if liste[i] + liste[j] == hedef:\n                return (i, j)\n    return None\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(131,134,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','while True:\n    satir = input()\n    if satir == \'son\':\n        break\n    try:\n        a, b = satir.split()\n        print(f\'{float(a) / float(b):.2f}\')\n    except ZeroDivisionError:\n        print(\'Sifira bolunemez\')\n    except ValueError:\n        print(\'Gecersiz giris\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(132,135,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','import math\nr = float(input())\nprint(f\'{math.pi * r * r:.2f}\')\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(133,136,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','a = int(input())\nb = int(input())\nc = int(input())\nbuyuk = a\nkucuk = a\nfor x in (b, c):\n    if x > buyuk:\n        buyuk = x\n    if x < kucuk:\n        kucuk = x\nprint(buyuk, kucuk)\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(134,137,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def faktoriyel(n):\n    if n < 0:\n        return -1\n    s = 1\n    for i in range(2, n + 1):\n        s *= i\n    return s\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(135,138,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','kelimeler = input().split()\nprint(len(kelimeler))\nen = \'\'\nfor k in kelimeler:\n    if len(k) > len(en):\n        en = k\nprint(en)\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(136,139,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def en_basarili(notlar):\n    en_iyi, en_ort = None, -1\n    for isim in sorted(notlar):\n        l = notlar[isim]\n        ort = sum(l) / len(l) if l else 0\n        if ort > en_ort:\n            en_iyi, en_ort = isim, ort\n    return en_iyi\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(137,140,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def ikili_ara(liste, x):\n    sol, sag = 0, len(liste) - 1\n    while sol <= sag:\n        orta = (sol + sag) // 2\n        if liste[orta] == x:\n            return orta\n        if liste[orta] < x:\n            sol = orta + 1\n        else:\n            sag = orta - 1\n    return -1\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(138,141,'python3',0,0,0,0,0,18,100,'','',NULL,'10, 20, ...','n = int(input())\r\nfor k in range(1, 6):\r\n    print(f\'{n} x {k} = {n * k}\')',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,10240,'','',1,0,NULL),
(139,142,'python3',0,0,0,0,0,18,100,'','',NULL,'10, 20, ...','def en_uzun_kelime(cumle):\r\n    en = \'\'\r\n    for k in cumle.split():\r\n        if len(k) > len(en):\r\n            en = k\r\n    return en',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,10240,'','',1,0,NULL),
(142,145,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','def mukemmel_mi(n):\n    if n < 2:\n        return False\n    return sum(i for i in range(1, n) if n % i == 0) == n\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL),
(143,146,'python3',0,0,0,0,0,18,100,'','',1,'10, 20, ...','class Dikdortgen:\n    def __init__(self, en, boy):\n        if en <= 0 or boy <= 0:\n            raise ValueError(\'gecersiz\')\n        self.en = en\n        self.boy = boy\n\n    def alan(self):\n        return self.en * self.boy\n\n    def cevre(self):\n        return 2 * (self.en + self.boy)\n\n    def kare_mi(self):\n        return self.en == self.boy\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','twig',0,NULL,0,1,0,NULL,NULL,NULL,NULL,NULL,NULL,3,200,NULL,0,0,0,'','',0,0,NULL);
